import time

def mjeri_vrijeme(func):
    def wrapper(*args):
        start = time.perf_counter()
        rezultat = func(*args)
        end = time.perf_counter()
        print(f'{func.__name__}: {end-start:.4f}s')
        return rezultat
    return wrapper

@mjeri_vrijeme
def spora_funkcija():
    time.sleep(1)
    return 'gotovo'

spora_funkcija()

