from abc import ABC, abstractmethod

class Oblik(ABC):
    @abstractmethod
    def povrsina(self) -> float:
        pass

class Krug(Oblik):
    def __init__(self, r):
        self.r = r
    def povrsina(self) -> float:
        return 3.14159 * self.r ** 2

k = Krug(5)
print(f'Površina: {k.povrsina():.2f}')

from abc import ABC, abstractmethod

class Plugin(ABC):
    @abstractmethod
    def ime(self) -> str: pass
    @abstractmethod
    def izvrsi(self, podaci: str) -> str: pass

class UpperPlugin(Plugin):
    def ime(self): return 'UPPERCASE'
    def izvrsi(self, podaci): return podaci.upper()

class ReversePlugin(Plugin):
    def ime(self): return 'REVERSE'
    def izvrsi(self, podaci): return podaci[::-1]

plugins = [UpperPlugin(), ReversePlugin()]
tekst = 'Hello'
for p in plugins:
    print(f'{p.ime()}: {p.izvrsi(tekst)}')

