import multiprocessing

def radnik(brojac, lock):
    for _ in range(1000):
        with lock:
            brojac.value += 1

if __name__ == '__main__':
    brojac = multiprocessing.Value('i', 0)
    lock = multiprocessing.Lock()
    procesi = [multiprocessing.Process(target=radnik, args=(brojac, lock)) for _ in range(4)]
    for p in procesi: p.start()
    for p in procesi: p.join()
    print(f'Broja■: {brojac.value}')

